function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H/2 + 50 * Math.sin(t));
  ctx.lineTo(W, H/2 + 50 * Math.sin(t + Math.PI));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, H/2 - 50 * Math.sin(t));
  ctx.lineTo(W, H/2 - 50 * Math.sin(t + Math.PI));
  ctx.stroke();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.rect(50 + 20 * Math.sin(2*t), H/2 - 25, 50, 50);
  ctx.rect(W - 100 + 20 * Math.sin(2*t + Math.PI), H/2 - 25, 50, 50);
  ctx.stroke();
  ctx.restore();
}
